import React from 'react';
import Slider from 'react-slick';
import { Box, Button } from '@mui/material';
import 'slick-carousel/slick/slick.css';
import 'slick-carousel/slick/slick-theme.css';

// Slider İçeriği
const slides = [
  // ... your slides data
];

const TechCareerSlider = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 5000,
    arrows: true,
    responsive: [
      {
        breakpoint: 1024, // Tablets (landscape)
        settings: {
          slidesToShow: 2, // Show 2 slides on tablets
        },
      },
      {
        breakpoint: 768, // Tablets (portrait) and smaller screens
        settings: {
          slidesToShow: 1, // Show 1 slide on smaller screens
          arrows: false, // Hide arrows on smaller screens
        },
      },
    ],
  };

  return (
    <Box sx={{ backgroundColor: '#F5F9FF', py: 4 }}>
      <Slider {...settings}>
        {slides.map((slide) => (
          <Box key={slide.id} sx={{ px: 2, textAlign: 'center' }}>
            <Button
              href={slide.link}
              sx={{
                p: 0,
                display: 'block',
                textDecoration: 'none',
                '&:hover': {
                  transform: 'scale(1.05)',
                  transition: 'transform 0.3s ease',
                },
              }}
            >
              <Box
                component="img"
                src={slide.image}
                alt={slide.alt}
                sx={{
                  width: '100%', // Ensures image fills container width
                  height: 'auto',
                  maxWidth: 'calc(33.33% - 4px)', // Adjust for margins (3 slides per row)
                  mx: 'auto',
                  borderRadius: 2,
                  boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                }}
              />
            </Button>
          </Box>
        ))}
      </Slider>
    </Box>
  );
};

export default TechCareerSlider;
